//! `image-to-text`: an image to text about it, such as the text it shows, generated by a vision encoder-decoder such as `TrOCR`, as `transformers`' image-to-text pipeline gave it before `transformers` 5, or by Florence-2 for a task prompt, as its processor and `generate` give it.

use serde::{Deserialize, Serialize};
use singe::{Shape, Tensor};

use crate::{
    error::{Error, Result},
    head::{Seq2SeqInput, Seq2SeqLm},
    model,
    model::multimodal::florence2::{Florence2Prompts, answers::ParsedAnswer},
    processor::{
        image::{Image, ImagePreprocessor},
        text::TextTokenizer,
    },
    source::{LoadOptions, Source},
    task::{Pipeline, seq2seq::Seq2SeqParameters},
};

#[derive(Debug)]
pub struct ImageToTextPipeline {
    model: Seq2SeqLm,
    processor: ImagePreprocessor,
    tokenizer: TextTokenizer,
    prompts: Option<Florence2Prompts>,
    options: LoadOptions,
}

#[derive(Debug, Clone, PartialEq, Eq, Default, Deserialize)]
#[serde(default)]
pub struct ImageToTextParameters {
    #[serde(flatten)]
    pub generation: Seq2SeqParameters,
    /// A prompting model's task token, such as Florence-2's `<OCR>`, or its question; `<CAPTION>` when `None`.
    pub prompt: Option<String>,
}

/// The generated text, and for a task that locates things, as Florence-2's `<OD>` does, its answer parsed as `post_process_generation` parses it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ImageText {
    pub generated_text: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parsed: Option<ParsedAnswer>,
}

/// The task a prompting model runs without a prompt.
const DEFAULT_PROMPT: &str = "<CAPTION>";

impl Pipeline for ImageToTextPipeline {
    type Input = Image;

    type Parameters = ImageToTextParameters;

    type Output = ImageText;

    fn load(source: &Source, options: LoadOptions) -> Result<Self> {
        Ok(Self {
            model: model::load(source, options)?,
            processor: ImagePreprocessor::load(source)?,
            tokenizer: TextTokenizer::load(source)?,
            prompts: Florence2Prompts::load(source)?,
            options,
        })
    }

    fn run_one(&self, image: &Self::Input, parameters: &Self::Parameters) -> Result<Self::Output> {
        let pixels =
            self.processor
                .preprocess(image, self.options.device, self.options.data_type)?;
        let Seq2SeqParameters {
            max_new_tokens,
            compile,
        } = parameters.generation;
        let Some(prompts) = &self.prompts else {
            if parameters.prompt.is_some() {
                return Err(Error::unsupported("a prompt for a model that reads none"));
            }
            return Ok(ImageText {
                generated_text: self.model.generate_from(
                    &self.tokenizer,
                    Seq2SeqInput::Pixels(&pixels),
                    max_new_tokens,
                    compile,
                )?,
                parsed: None,
            });
        };
        let prompt = parameters.prompt.as_deref().unwrap_or(DEFAULT_PROMPT);
        let text = prompts.text(prompt)?;
        let ids = self.tokenizer.encode(&text, false)?;
        let count = i64::try_from(ids.len()).map_err(|_| Error::invalid("a prompt too long"))?;
        let tokens =
            Tensor::from_vec(self.options.device, Shape::create([1, count])?, ids.clone())?;
        let encoded = self.model.encode(Seq2SeqInput::Prompted {
            tokens: &tokens,
            pixels: &pixels,
        })?;
        let generated = self.model.generate(
            &encoded,
            &ids,
            &[self.model.decoder_start()?],
            max_new_tokens,
            compile,
        )?;
        // Location tokens are special, so the answer is decoded with them, as Florence-2's post-processing reads it.
        let answer = Florence2Prompts::answer(&self.tokenizer.decode(&generated, false)?);
        Ok(ImageText {
            parsed: prompts.parsed(prompt, &answer, (image.width, image.height)),
            generated_text: answer,
        })
    }
}
